/*
 * Error Type
 */


/*
 *  typedef struct tagBACSTAC_ERROR_TYPE
 *  {
 *      BACSTAC_ERROR_CLASS errClass;
 *      BACSTAC_ERROR_CODE  errCode;
 *  } BACSTAC_ERROR_TYPE, *PBACSTAC_ERROR_TYPE;
 */


